// Sample pictures for std.imageSample 1 to 6 (index 0, the landscape, lives in
// sample-image-landscape.json). Each constant is a 96-pixel-wide RGBA buffer:
// row-major, 4 bytes per pixel (r, g, b, a), base64, decoded by image-data.ts.
// There is no generator script: a replacement picture is re-encoded to the same
// format and pasted in, at the same index, so saved expressions keep their meaning.
//
// Origins:
//   EYE (1): an iris drawn for the project with an AI image tool on 2026-11-12,
//     after the earlier sample; reduced to 96 x 97.
//   PORTRAIT (2): Aajonus Vonderplanitz, used with the Aajonus person data.
//   BOOK (3): the cover of Aajonus Vonderplanitz's book "We Want to Live".
//   FENNEL (4): the project's own fennel picture (the original of the common fennel
//     drawing in fenel/modules/encyclopedia/life-pictures.fenel), generated for
//     Fenel with an AI image-generation tool on 2026-11-11, on white, reduced to
//     96 x 136; project licence.
//   TOMATO (5): the project's own tomato picture, generated for Fenel with an AI
//     image-generation tool on 2026-11-11 (distros/narthex/solid/public/demo/
//     recipe-pictures/tomato.png), on white, reduced to 96 x 96; project licence.
//   STEAK (6): photograph by Romain Leclercq.

export const EYE_WIDTH = 96;
export const EYE_HEIGHT = 97;
export const EYE_RGBA_B64 = "";

export const BOOK_WIDTH = 96;
